    assert pruned_cpp.SerializeToString() == pruned_py.SerializeToString()
    inits = {t.name: t for t in pruned_cpp.graph.initializer}
    # (nq+nk+nv) at new_num_heads=4, D=4 -- 3 equal-width segments since
